import { Activity, ArrowDownRight, ArrowRight, Bandage, BookOpen, Check, CheckCircle2, ChevronDown, ClipboardList, Copy, Cross, ExternalLink, FileText, HeartPulse, Hospital, Info, ListChecks, LocateFixed, MapPin, Menu, Moon, Phone, Play, Plus, Printer, RotateCcw, Search, ShieldCheck, Siren, Sun, Trash2, UserRound, Users, X } from "lucide-react";
