type Contact = { id: string; name: string; relation: string; phone: string; notes: string };
type ServiceLine = { id: string; name: string; phone: string; notes: string; source?: string; sourceUrl?: string };
const readStore = <T,>(key: string, fallback: T): T => { try { const value = localStorage.getItem(key); return value ? JSON.parse(value) : fallback; } catch { return fallback; } };
const writeStore = (key: string, value: unknown) => { try { localStorage.setItem(key, JSON.stringify(value)); } catch {} };
const makeId = () => Math.random().toString(36).slice(2, 10);
const copyToClipboard = async (value: string) => {
  try {
    if (!navigator.clipboard?.writeText) return false;
    await navigator.clipboard.writeText(value);
    return true;
  } catch {
    return false;
  }
};
const DemoMode = createContext(false);

function Link({ href, ...props }: Omit<ComponentProps<typeof RouterLink>, "to"> & { href: string }) {
  return <RouterLink to={href} {...props} />;
}

const navItems = [
  ["/", "Home", Activity], ["/emergency", "Emergency", Siren], ["/hospitals", "Nearby care", Hospital],
  ["/first-aid", "First aid", Bandage], ["/contacts", "Contacts", Users],
  ["/preparedness", "Preparedness", ListChecks], ["/incident", "Incident notes", FileText], ["/about", "About", Info],
] as const;

function AppShell({ children }: { children: ReactNode }) {
  const { pathname: path } = useLocation();
  const [mobileOpen, setMobileOpen] = useState(false);
  const [dark, setDark] = useState(() => localStorage.getItem("lifelink-theme") === "dark");
  const [demoMode,setDemoMode]=useState(()=>localStorage.getItem("lifelink-demo-mode")==="true");
  useEffect(() => { document.documentElement.classList.toggle("dark", dark); localStorage.setItem("lifelink-theme", dark ? "dark" : "light"); }, [dark]);
  useEffect(() => setMobileOpen(false), [path]);
  useEffect(() => { const label=navItems.find(([route])=>route===path)?.[1]||"Page not found";document.title=`${label} | LifeLink AI`; },[path]);
  const toggleDemo=()=>{const next=!demoMode;setDemoMode(next);localStorage.setItem("lifelink-demo-mode",String(next));};
  return <DemoMode.Provider value={demoMode}><div className="app-shell">
    <header className={`topbar ${mobileOpen ? "mobile-open" : ""}`}>
      <Link href="/" className="brand" aria-label="LifeLink AI home"><span className="brand-mark"><HeartPulse size={21}/></span><span>LifeLink <span style={{color:"hsl(var(--primary))"}}>AI</span></span></Link>
      <nav className="nav-links" aria-label="Main navigation">{navItems.map(([href,label,Icon])=><Link key={href} href={href} className={`nav-link ${path===href?"active":""}`}><Icon size={15} style={{verticalAlign:"-3px",marginRight:5}}/>{label}</Link>)}</nav>
      <div className="row">
        <button className={`btn outline small demo-toggle ${demoMode?"demo-active":""}`} aria-pressed={demoMode} onClick={toggleDemo}><Play size={13}/>{demoMode?"Demo mode on":"Demo mode"}</button>
        <button className="icon-button" aria-label={`Switch to ${dark?"light":"dark"} theme`} data-testid="button-theme" onClick={()=>setDark(!dark)}>{dark?<Sun size={18}/>:<Moon size={18}/>}</button>
        <button className="icon-button mobile-menu" aria-label={mobileOpen?"Close menu":"Open menu"} aria-expanded={mobileOpen} onClick={()=>setMobileOpen(!mobileOpen)}>{mobileOpen?<X size={19}/>:<Menu size={19}/>}</button>
      </div>
    </header>
    {demoMode&&<div className="demo-banner" role="status"><strong>Presentation demo is on.</strong> Example content is labeled, and live facilities are never simulated.</div>}
    <main className="main">{children}<footer className="footer"><span>LifeLink AI · Prepared for the moments that matter.</span><span>Map data: <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">OpenStreetMap contributors</a> · First-aid references: <a href="https://www.redcross.org/take-a-class/first-aid" target="_blank" rel="noreferrer">American Red Cross</a> and <a href="https://www.nhs.uk/conditions/first-aid/" target="_blank" rel="noreferrer">NHS</a>.</span><span>Not a substitute for emergency professionals.</span></footer></main>
    <nav className="bottom-nav" aria-label="Quick navigation">{navItems.slice(0,5).map(([href,label,Icon])=><Link key={href} href={href} className={path===href?"active":""}><Icon size={18}/><span>{label==="Nearby care"?"Care":label}</span></Link>)}</nav>
  </div></DemoMode.Provider>;
}

function Heading({ eyebrow, title, text, children }: { eyebrow:string;title:string;text?:string;children?:ReactNode }) {
  return <div className="between" style={{alignItems:"flex-end",marginBottom:27,flexWrap:"wrap"}}><div><div className="eyebrow">{eyebrow}</div><h1 style={{fontSize:"clamp(34px,4vw,48px)",margin:"8px 0 9px"}}>{title}</h1>{text&&<div className="muted" style={{maxWidth:760,lineHeight:1.65}}>{text}</div>}</div>{children}</div>;
}

